 corkboard:function(k){var note=function(x,y,c,t1,t2,r,d){return '<g transform="translate('+x+' '+y+') rotate('+r+')"><g class="cm-flutter" style="animation-delay:'+d+'s"><rect width="66" height="46" fill="'+c+'" stroke="'+I+'" stroke-width="1.4"/><circle cx="33" cy="4" r="3.4" fill="#e0453a" stroke="'+I+'" stroke-width="1.2"/><text x="33" y="24" text-anchor="middle" font-size="8" font-weight="800" fill="'+I+'" font-family="sans-serif">'+t1+'</text><text x="33" y="36" text-anchor="middle" font-size="8" font-weight="800" fill="'+I+'" font-family="sans-serif">'+t2+'</text></g></g>';};
  return '<rect width="360" height="180" fill="#f4ead8"/><rect x="8" y="58" width="344" height="116" rx="6" fill="#c9965e" stroke="#8d5a33" stroke-width="6"/><g fill="#b8844c" opacity=".6"><circle cx="40" cy="80" r="2"/><circle cx="90" cy="150" r="2"/><circle cx="300" cy="90" r="2"/><circle cx="250" cy="160" r="2"/><circle cx="330" cy="140" r="2"/></g>'+
  note(12,62,'#fff3a8','ย้ายไปบริษัทอื่น','ต้องยินยอม',-5,0)+note(74,104,'#c8f0d8','ลูกจ้าง 10 คน+','ต้องมีข้อบังคับ',4,.4)+note(248,116,'#ffd6e0','ชาย–หญิง','ต้องเท่าเทียม',-4,.8)+note(276,66,'#d6e8ff','ห้ามคุกคาม','ทางเพศ',6,1.2);},
